<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$pdo=sv_next_db();require_once __DIR__.'/../includes/engagement.php';sv_engagement_db();sv_seed_change_baselines();$errors=[];
$elections=$pdo->query('SELECT id,title FROM elections ORDER BY start_datetime DESC')->fetchAll();$id=int_input('election_id',(int)($elections[0]['id']??0));$valid=in_array($id,array_map('intval',array_column($elections,'id')),true);
$meta=['organization'=>'','department'=>'','school_year'=>''];$s=$pdo->prepare('SELECT * FROM election_metadata WHERE election_id=?');$s->execute([$id]);$meta=array_merge($meta,$s->fetch()?:[]);
$form=['id'=>0,'kind'=>'event','title'=>'','description'=>'','resource_url'=>'','event_at'=>'','status'=>'draft'];
if(is_post()){
 require_csrf();if(!$valid)$errors[]='Choose an existing election.';
 if(input('action')==='metadata'){
  foreach(['organization'=>100,'department'=>100,'school_year'=>30] as $k=>$max){$meta[$k]=input($k,'');if(mb_strlen($meta[$k])>$max)$errors[]='Shorten '.$k.'.';}
  if(!$errors){$s=$pdo->prepare('INSERT INTO election_metadata(election_id,organization,department,school_year) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE organization=VALUES(organization),department=VALUES(department),school_year=VALUES(school_year)');$s->execute([$id,$meta['organization'],$meta['department'],$meta['school_year']]);sv_record_election_change($id);audit_log('election_metadata_saved','Election #'.$id.' classification updated.');flash_success('Election filters saved.');redirect('admin/resources.php?election_id='.$id);}
 }elseif(input('action')==='resource'){
  foreach($form as $k=>$value)$form[$k]=$k==='id'?int_input('id'):input($k,'');
  if(!in_array($form['kind'],['event','video','material'],true))$errors[]='Choose a valid resource type.';
  if(!in_array($form['status'],['draft','published','withdrawn'],true))$errors[]='Choose a publication status.';
  if(mb_strlen($form['title'])<3||mb_strlen($form['title'])>150)$errors[]='Use a title of 3–150 characters.';
  if(mb_strlen($form['description'])<10||mb_strlen($form['description'])>10000)$errors[]='Use a description of 10–10,000 characters.';
  if(strlen($form['resource_url'])>2000||!sv_valid_resource_url($form['resource_url']))$errors[]='Use a full HTTPS resource link.';
  if(in_array($form['kind'],['video','material'],true)&&!$form['resource_url'])$errors[]='Add a link for the video or material.';
  $at=null;if($form['event_at']!==''){$dt=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$form['event_at'],new DateTimeZone(APP_TIMEZONE));if(!$dt||$dt->format('Y-m-d\TH:i')!==$form['event_at'])$errors[]='Enter a valid event date.';else $at=$dt->format('Y-m-d H:i:s');}
  if($form['kind']==='event'&&!$at)$errors[]='Set the event date and time.';
  if($form['id']){$s=$pdo->prepare('SELECT id FROM election_forum WHERE id=? AND election_id=?');$s->execute([$form['id'],$id]);if(!$s->fetchColumn())$errors[]='Resource not found in this election.';}
  if(!$errors){$values=[$form['kind'],$form['title'],$form['description'],$form['resource_url'],$at,$form['status']];if($form['id']){$s=$pdo->prepare('UPDATE election_forum SET kind=?,title=?,description=?,resource_url=?,event_at=?,status=? WHERE id=? AND election_id=?');$s->execute([...$values,$form['id'],$id]);}else{$s=$pdo->prepare('INSERT INTO election_forum(kind,title,description,resource_url,event_at,status,election_id) VALUES (?,?,?,?,?,?,?)');$s->execute([...$values,$id]);}audit_log('forum_resource_saved','Forum resource saved for election #'.$id.'.');flash_success('Forum resource saved.');redirect('admin/resources.php?election_id='.$id);}
 }else $errors[]='Choose a valid action.';
}elseif(int_input('resource_id')){$s=$pdo->prepare('SELECT * FROM election_forum WHERE id=? AND election_id=?');$s->execute([int_input('resource_id'),$id]);$form=$s->fetch()?:$form;}
$s=$pdo->prepare('SELECT * FROM election_forum WHERE election_id=? ORDER BY updated_at DESC');$s->execute([$id]);$items=$s->fetchAll();$pageTitle='Election resources';$activeNav='resources.php';require __DIR__.'/../includes/header.php';
?>
<div class="feature-page stack"><h2>Election resources and filters</h2><form method="get" class="feature-toolbar"><label for="resource-election">Election</label><select class="input" id="resource-election" name="election_id"><?php foreach($elections as $e): ?><option value="<?= (int)$e['id'] ?>" <?= (int)$e['id']===$id?'selected':'' ?>><?= e($e['title']) ?></option><?php endforeach; ?></select><button class="btn btn--secondary">Choose election</button></form><?php sv_feature_errors($errors);if($valid): ?>
<details class="resource-editor" open><summary>Organization, department, and school year</summary><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="metadata"><input type="hidden" name="election_id" value="<?= $id ?>"><?php foreach(['organization'=>'Organization','department'=>'Department','school_year'=>'School year'] as $k=>$label): ?><label for="meta-<?= e($k) ?>"><?= e($label) ?></label><input id="meta-<?= e($k) ?>" class="input" name="<?= e($k) ?>" maxlength="<?= $k==='school_year'?30:100 ?>" value="<?= e($meta[$k]) ?>"><?php endforeach; ?><button class="btn btn--primary">Save election filters</button></form></details>
<details class="resource-editor" <?= $form['id']||$errors?'open':'' ?>><summary><?= $form['id']?'Edit forum resource':'Add forum resource' ?></summary><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="resource"><input type="hidden" name="election_id" value="<?= $id ?>"><input type="hidden" name="id" value="<?= (int)$form['id'] ?>"><label for="resource-kind">Resource type</label><select class="input" id="resource-kind" name="kind"><?php foreach(['event'=>'Event','video'=>'Debate video','material'=>'Campaign material'] as $k=>$label): ?><option value="<?= e($k) ?>" <?= $form['kind']===$k?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><label for="resource-title">Title</label><input class="input" id="resource-title" name="title" minlength="3" maxlength="150" required value="<?= e($form['title']) ?>"><label for="resource-description">Description</label><textarea class="input" id="resource-description" name="description" rows="5" minlength="10" maxlength="10000" required><?= e($form['description']) ?></textarea><label for="resource-link">Resource link (HTTPS)</label><input class="input" id="resource-link" name="resource_url" type="url" maxlength="2000" value="<?= e($form['resource_url']) ?>"><label for="resource-time">Event date and time (Philippine time)</label><input class="input" id="resource-time" name="event_at" type="datetime-local" value="<?= e(empty($form['event_at'])?'':to_datetime($form['event_at'])->format('Y-m-d\TH:i')) ?>"><label for="resource-status">Publication status</label><select class="input" id="resource-status" name="status"><?php foreach(['draft','published','withdrawn'] as $status): ?><option <?= $form['status']===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select><button class="btn btn--primary">Save forum resource</button></form></details>
<section><h2>Saved forum resources</h2><?php if(!$items): ?><p>No resources yet. Add an event, debate video, or official campaign link.</p><?php endif; ?><?php foreach($items as $item): ?><article class="feature-entry"><h3><?= e($item['title']) ?></h3><p><?= e($item['kind'].' · '.$item['status']) ?></p><a class="link" href="<?= e(url('admin/resources.php?election_id='.$id.'&resource_id='.(int)$item['id'])) ?>">Edit resource</a></article><?php endforeach; ?></section><?php endif; ?></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
